def expect_order(self, order, output):
    # skip the header and match the start of each row
    for expect, line in zip(order, output.splitlines()[2:]):
        # do this instead of startswith for nicer pytest output
        assert line[: len(expect)] == expect

def test_simple(self, invoke):
    result = invoke(["routes"])
    assert result.exit_code == 0
    self.expect_order(["aaa_post", "static", "yyy_get_post"], result.output)

def test_sort(self, app, invoke):
    default_output = invoke(["routes"]).output
    endpoint_output = invoke(["routes", "-s", "endpoint"]).output
    assert default_output == endpoint_output
    self.expect_order(
        ["static", "yyy_get_post", "aaa_post"],
        invoke(["routes", "-s", "methods"]).output,
    )
    self.expect_order(
        ["yyy_get_post", "static", "aaa_post"],
        invoke(["routes", "-s", "rule"]).output,
    )
    match_order = [r.endpoint for r in app.url_map.iter_rules()]
    self.expect_order(match_order, invoke(["routes", "-s", "match"]).output)

def test_all_methods(self, invoke):
    output = invoke(["routes"]).output
    assert "GET, HEAD, OPTIONS, POST" not in output
    output = invoke(["routes", "--all-methods"]).output
    assert "GET, HEAD, OPTIONS, POST" in output

def test_no_routes(self, invoke_no_routes):
    result = invoke_no_routes(["routes"])
    assert result.exit_code == 0
    assert "No routes were registered." in result.output

@click.command("routes", short_help="Show the routes for the app.")
@click.option(
    "--sort",
    "-s",
    type=click.Choice(("endpoint", "methods", "rule", "match")),
    default="endpoint",
    help=(
        'Method to sort routes by. "match" is the order that Flask will match '
        "routes when dispatching a request."
    ),
)
@click.option("--all-methods", is_flag=True, help="Show HEAD and OPTIONS methods.")
@with_appcontext
def _format_subdomain(rule) -> str:
    """Get the absolute domain for a rule including the subdomain.

    If ``host_matching`` or ``subdomain_matching`` is enabled, the domain
    is built from the app's ``SERVER_NAME`` and the rule's subdomain. The
    subdomain placeholder ``<subdomain>`` is preserved as is.
    """
    if not current_app.config["SERVER_NAME"]:
        # Not able to determine the domain without a SERVER_NAME.
        hosts = rule.endpoint, rule.subdomain
    elif current_app.url_map.host_matching:
        hosts = rule.endpoint, rule.host or ""
    elif rule.subdomain in (None, ""):
        hosts = rule.endpoint, current_app.config["SERVER_NAME"]
    else:
        hosts = (
            rule.endpoint,
            f"{rule.subdomain}.{current_app.config['SERVER_NAME']}",
        )

    return hosts[1]


def routes_command(sort: str, all_methods: bool) -> None:
    """Show all registered routes with endpoints and methods."""
    rules = list(current_app.url_map.iter_rules())
    if not rules:
        click.echo("No routes were registered.")
        return

    ignored_methods = set(() if all_methods else ("HEAD", "OPTIONS"))

    if sort in ("endpoint", "rule"):
        rules = sorted(rules, key=attrgetter(sort))
    elif sort == "methods":
        rules = sorted(rules, key=lambda rule: sorted(rule.methods))  # type: ignore

    rule_methods = [
        ", ".join(sorted(rule.methods - ignored_methods))  # type: ignore
        for rule in rules
    ]

    headers = ("Endpoint", "Methods", "Domain", "Rule")
    widths = (
        max(len(rule.endpoint) for rule in rules),
        max(len(methods) for methods in rule_methods),
        max(len(_format_subdomain(rule)) for rule in rules),
        max(len(rule.rule) for rule in rules),
    )
    widths = [max(len(h), w) for h, w in zip(headers, widths)]
    row = "{{0:<{0}}}  {{1:<{1}}}  {{2:<{2}}}  {{3:<{3}}}".format(*widths)

    click.echo(row.format(*headers).strip())
    click.echo(row.format(*("-" * width for width in widths)))

    for rule, methods in zip(rules, rule_methods):
        subdomain = _format_subdomain(rule)
        click.echo(row.format(rule.endpoint, methods, subdomain, rule.rule).rstrip())
